#include "instaham/cutter/ShrinkingBall.hpp"
#include "instaham/MaskUtils.hpp"
#include <algorithm>
#include <cmath>
#include <limits>
namespace instaham {
static double angle(const cv::Point2d&p,const cv::Point2d&c,const cv::Point2d&q){cv::Vec2d u(p.x-c.x,p.y-c.y),v(q.x-c.x,q.y-c.y);double un=hypot(u[0],u[1]),vn=hypot(v[0],v[1]);if(un<=1e-12||vn<=1e-12)return 0;double d=std::clamp(dot2({u[0]/un,u[1]/un},{v[0]/vn,v[1]/vn}),-1.0,1.0);return acos(d)*180/CV_PI;}
static std::pair<int,double> nearest(const std::vector<cv::Point2d>&s,const cv::Point2d&c,int ex){int bi=-1;double bd=1e300;for(int i=0;i<(int)s.size();i++){if(i==ex)continue;double dx=s[i].x-c.x,dy=s[i].y-c.y,d=dx*dx+dy*dy;if(d<bd){bd=d;bi=i;}}return {bi,sqrt(bd)};}
static std::tuple<int,double,double> nearestAngle(const std::vector<cv::Point2d>&s,const cv::Point2d&c,int pi,double minA){int bi=-1;double bd=1e300,ba=nanValue();for(int i=0;i<(int)s.size();i++){if(i==pi)continue;double a=angle(s[pi],c,s[i]);if(a<minA)continue;double dx=s[i].x-c.x,dy=s[i].y-c.y,d=dx*dx+dy*dy;if(d<bd){bd=d;bi=i;ba=a;}}return {bi,sqrt(bd),ba};}
static double maRadius(const cv::Point2d&p,const cv::Point2d&q,const cv::Vec2d&n,double eps){cv::Vec2d d(p.x-q.x,p.y-q.y);double d2=dot2(d,d),den=2*dot2(n,d);if(!std::isfinite(d2)||d2<=0||!std::isfinite(den)||den<=eps)return nanValue();return d2/den;}
ShrinkingBallResult runShrinkingBall(const OutlineResult&o,const ShrinkingBallConfig&cfg){ShrinkingBallResult out;auto&s=o.smooth;double minx=1e300,miny=1e300,maxx=-1e300,maxy=-1e300;for(auto&p:s){minx=std::min(minx,p.x);miny=std::min(miny,p.y);maxx=std::max(maxx,p.x);maxy=std::max(maxy,p.y);}double initial=std::max(cfg.initialRadiusFactor*hypot(maxx-minx,maxy-miny),10.0);out.candidates.reserve(s.size());for(int pi=0;pi<(int)s.size();pi++){PointRadius r;r.pIndex=pi;r.p=s[pi];r.normal=o.normals[pi];double rho=initial;int qi=-1;double finalA=nanValue();for(int it=1;it<=cfg.maxIterations;it++){cv::Point2d c(r.p.x-rho*r.normal[0],r.p.y-rho*r.normal[1]);auto [qidx,nd]=nearest(s,c,pi);if(qidx<0)break;qi=qidx;double th=angle(r.p,c,s[qi]);bool potential=std::abs(nd-rho)<=cfg.maximalityTolPx;if(potential&&th<cfg.minSeparationDeg){auto [q2,dd,a2]=nearestAngle(s,c,pi,cfg.minSeparationDeg);if(q2<0)break;qi=q2;th=a2;potential=false;}else if(potential){r.converged=true;finalA=th;break;}double rn=maRadius(r.p,s[qi],r.normal,cfg.denomEps);if(!std::isfinite(rn)||rn>rho+1e-7)break;if(std::abs(rn-rho)<=cfg.radiusTolPx){if(th>=cfg.minSeparationDeg){rho=rn;r.converged=true;finalA=th;break;}auto [q2,dd,a2]=nearestAngle(s,c,pi,cfg.minSeparationDeg);if(q2<0)break;qi=q2;th=a2;double ra=maRadius(r.p,s[qi],r.normal,cfg.denomEps);if(!std::isfinite(ra)||ra>rho+1e-7)break;if(std::abs(ra-rho)<=cfg.radiusTolPx){rho=ra;r.converged=true;finalA=th;break;}rho=ra;}else rho=rn;if(rho<cfg.minRadiusPx)break;}
        r.radius=rho;r.center={r.p.x-rho*r.normal[0],r.p.y-rho*r.normal[1]};auto [q2,dd,a2]=nearestAngle(s,r.center,pi,cfg.minSeparationDeg);if(q2>=0){qi=q2;finalA=a2;}else if(qi<0)qi=nearest(s,r.center,pi).first;if(qi<0)qi=pi;r.qIndex=qi;r.q=s[qi];if(!std::isfinite(finalA))finalA=angle(r.p,r.center,r.q);r.contactAngleDeg=finalA;out.candidates.push_back(r);}return out;}
}
